'use client';

import * as React from 'react';
import { motion, type Variants } from 'motion/react';

import {
  getVariants,
  useAnimateIconContext,
  IconWrapper,
  type IconProps,
} from '@/components/animate-ui/icons/icon';

type MailProps = IconProps<keyof typeof animations>;

const CLOSED_BODY =
  'M21.2 4.4c.5 .38 .8 .97 .8 1.6v12a2 2 0 0 1 -2 2H4a2 2 0 0 1 -2 -2V6a2 2 0 0 1 .8 -1.6l8 0a2 2 0 0 1 2.4 0l8 0Z';
const OPEN_BODY =
  'M21.2 8.4c.5 .38 .8 .97 .8 1.6v10a2 2 0 0 1 -2 2H4a2 2 0 0 1 -2 -2V10a2 2 0 0 1 .8 -1.6l8 -6a2 2 0 0 1 2.4 0l8 6Z';
const CLOSED_FLAP = 'm22 7 -8.97 5.7a1.94 1.94 0 0 1 -2.06 0L2 7';
const OPEN_FLAP = 'm22 10 -8.97 5.7a1.94 1.94 0 0 1 -2.06 0L2 10';

const animations = {
  default: {
    body: {
      initial: {
        d: CLOSED_BODY,
        transition: { duration: 0.35, ease: 'easeInOut' },
      },
      animate: {
        d: OPEN_BODY,
        transition: { duration: 0.45, ease: 'easeInOut' },
      },
    },
    flap: {
      initial: {
        d: CLOSED_FLAP,
        transition: { duration: 0.35, ease: 'easeInOut' },
      },
      animate: {
        d: OPEN_FLAP,
        transition: { duration: 0.45, ease: 'easeInOut' },
      },
    },
  } satisfies Record<string, Variants>,
  peek: {
    body: {
      initial: { d: CLOSED_BODY },
      animate: {
        d: [CLOSED_BODY, OPEN_BODY, OPEN_BODY, CLOSED_BODY],
        transition: {
          duration: 1.4,
          times: [0, 0.3, 0.7, 1],
          ease: 'easeInOut',
        },
      },
    },
    flap: {
      initial: { d: CLOSED_FLAP },
      animate: {
        d: [CLOSED_FLAP, OPEN_FLAP, OPEN_FLAP, CLOSED_FLAP],
        transition: {
          duration: 1.4,
          times: [0, 0.3, 0.7, 1],
          ease: 'easeInOut',
        },
      },
    },
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: MailProps) {
  const { controls } = useAnimateIconContext();
  const variants = getVariants(animations);

  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      initial="initial"
      animate={controls}
      {...props}
    >
      <motion.path
        d={CLOSED_BODY}
        variants={variants.body}
        initial="initial"
        animate={controls}
      />
      <motion.path
        d={CLOSED_FLAP}
        variants={variants.flap}
        initial="initial"
        animate={controls}
      />
    </motion.svg>
  );
}

function Mail(props: MailProps) {
  return <IconWrapper icon={IconComponent} {...props} />;
}

export {
  animations,
  Mail,
  Mail as MailIcon,
  type MailProps,
  type MailProps as MailIconProps,
};
